using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/opportunities"),Authorize] public class OpportunitiesApiController(ApplicationDbContext db,IAuditService audit):ControllerBase {
 private IQueryable<Opportunity> Scope(){var q=db.Opportunities.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.AssignedTo==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return q;}
 [HttpGet]public async Task<IActionResult>Get(){return Ok(await Scope().Select(x=>new{x.OpportunityId,x.OpportunityName,x.Amount,x.Probability,x.Stage,x.ExpectedCloseDate,x.Status,WeightedValue=x.Amount*x.Probability/100m}).ToListAsync());}
 [HttpGet("{id:int}")]public async Task<IActionResult>GetById(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.OpportunityId==id);if(x==null)return NotFound();return Ok(new{x.OpportunityId,x.OpportunityName,x.Amount,x.Probability,x.Stage,x.ExpectedCloseDate,x.Status,x.AssignedTo,WeightedValue=x.Amount*x.Probability/100m});}
 [HttpPost]public async Task<IActionResult>Create(Opportunity input){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(!new[]{"Qualification","Proposal","Negotiation","Won","Lost"}.Contains(input.Stage))return BadRequest(new{message="Invalid opportunity stage."});if(input.Amount<=0)return BadRequest(new{message="Opportunity Amount must be greater than 0."});if(input.Probability is <0 or >100)return BadRequest(new{message="Probability must be between 0 and 100."});if((input.Status=="Open"||string.IsNullOrWhiteSpace(input.Status))&&input.ExpectedCloseDate.Date<DateTime.Today)return BadRequest(new{message="Expected Close Date cannot be in the past."});input.OpportunityId=0;input.AssignedTo=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;if(input.Stage=="Won"||input.Stage=="Lost")input.Status="Closed";else input.Status=string.IsNullOrWhiteSpace(input.Status)?"Open":input.Status;db.Add(input);await db.SaveChangesAsync();await audit.WriteAsync("Create","Opportunity",input.OpportunityId.ToString());return Created($"/api/opportunities/{input.OpportunityId}",new{input.OpportunityId,input.OpportunityName,input.Amount,input.Stage});}
 [HttpPut("{id:int}")]public async Task<IActionResult>Update(int id, Opportunity input){var x=await Scope().FirstOrDefaultAsync(a=>a.OpportunityId==id);if(x==null)return NotFound();if(!ModelState.IsValid)return ValidationProblem(ModelState);if(!new[]{"Qualification","Proposal","Negotiation","Won","Lost"}.Contains(input.Stage))return BadRequest(new{message="Invalid opportunity stage."});if(input.Amount<=0)return BadRequest(new{message="Opportunity Amount must be greater than 0."});if(input.Probability is <0 or >100)return BadRequest(new{message="Probability must be between 0 and 100."});if((input.Status=="Open"||string.IsNullOrWhiteSpace(input.Status))&&input.ExpectedCloseDate.Date<DateTime.Today)return BadRequest(new{message="Expected Close Date cannot be in the past."});x.OpportunityName=input.OpportunityName;x.CustomerId=input.CustomerId;x.LeadId=input.LeadId;x.Amount=input.Amount;x.Probability=input.Probability;x.Stage=input.Stage;x.ExpectedCloseDate=input.ExpectedCloseDate;x.Notes=input.Notes;x.Status=input.Stage=="Won"||input.Stage=="Lost"?"Closed":(string.IsNullOrWhiteSpace(input.Status)?"Open":input.Status);await db.SaveChangesAsync();await audit.WriteAsync("Update","Opportunity",id.ToString());return NoContent();}
 [HttpDelete("{id:int}")]public async Task<IActionResult>Delete(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.OpportunityId==id);if(x==null)return NotFound();x.Status="Closed";x.Stage="Lost";await db.SaveChangesAsync();await audit.WriteAsync("Close","Opportunity",id.ToString());return NoContent();}
}
